import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境商品简报与渠道任务表","description":"","frontmatter":{"id":"P09","title":"跨境商品简报与渠道任务表","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting"],"order":109},"headers":[],"relativePath":"prompts/P09.md","filePath":"prompts/P09.md"}'),l={name:"prompts/P09.md"};function t(i,s,c,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p09-跨境商品简报与渠道任务表" tabindex="-1">P09 跨境商品简报与渠道任务表 <a class="header-anchor" href="#p09-跨境商品简报与渠道任务表" aria-label="Permalink to &quot;P09 跨境商品简报与渠道任务表&quot;">​</a></h1><p>类型：规划。替换项目：商品事实、市场、图片位置、语言与素材。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="./../ecommerce/cross-border">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请把商品事实和素材整理成跨境视觉制作简报，本次只做规划。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：Amazon US英文商品页（主图、副图、A+）；Shopify英文产品页与首页横幅；Shopee SG英文封面与规格图。</span></span>
<span class="line"><span>处理步骤：</span></span>
<span class="line"><span>1. 建立事实表，每项写已确认／未知与依据，商品属性和创作文案分开。</span></span>
<span class="line"><span>2. 建素材表，标明每张图承担外观、细节、布局还是风格角色，以及缺少的照片。</span></span>
<span class="line"><span>3. 建渠道矩阵：市场、语言、图片位置、买家问题、画面简报、准确文字、素材、导出要求、规则来源与核对日期。</span></span>
<span class="line"><span>4. 给每个位置独立分工，主图展示商品，副图解释结构，A+按当前模块，Shopify按主题，Shopee按市场。</span></span>
<span class="line"><span>5. 平台参数未核对时写待填；2000方图等可以作为制作建议，不能写成所有平台硬规定。</span></span>
<span class="line"><span>6. 选一张真实主体母版作为首项任务，说明完成后如何扩展，不直接批量生成整套。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出：事实表、素材表、渠道任务表、首项完整制作指令、待补素材和未核要求。本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const h=a(l,[["render",t]]);export{m as __pageData,h as default};
